#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/stat.h>

char* write_results(const char* results) {
    // Create a temporary file using tmpfile()
    FILE* tmpfile = tmpfile();
    if (tmpfile == NULL) {
        return NULL;
    }

    // Write results to the temporary file
    if (fprintf(tmpfile, "%s", results) < 0) {
        fclose(tmpfile);
        return NULL;
    }

    // Generate a unique filename with a timestamp
    char* filename = (char*)malloc(1024 * sizeof(char));
    if (filename == NULL) {
        fclose(tmpfile);
        return NULL;
    }

    snprintf(filename, 1024, "/tmp/results_%d.txt", (int)time(NULL));

    // Set secure file permissions (read/write for owner only)
    mode_t mode = S_IRUSR | S_IWUSR;
    if (chmod(filename, mode) != 0) {
        free(filename);
        fclose(tmpfile);
        return NULL;
    }

    // Reopen the file in write mode to ensure it's created
    FILE* final_file = fopen(filename, "w");
    if (final_file == NULL) {
        free(filename);
        fclose(tmpfile);
        return NULL;
    }

    // Write results again to ensure content is properly written
    if (fprintf(final_file, "%s", results) < 0) {
        fclose(final_file);
        free(filename);
        fclose(tmpfile);
        return NULL;
    }

    // Close both files
    fclose(final_file);
    fclose(tmpfile);

    return filename;
}
